package com.primehr.succession.domain;
import com.primehr.integration.administrative.AdministrativePositionTarget;import com.primehr.integration.humanresource.HumanResourceAssessmentSubject;import com.primehr.positionprofile.domain.PositionTargetType;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import static org.assertj.core.api.Assertions.*;
class SuccessionIntakeDomainTest{
 @Test void cycleEnforcesChronologyAndLifecycle(){assertThatThrownBy(()->new SuccessionCycle("A","C1","Cycle",null,"p",1,"fp","ch",LocalDate.of(2026,1,2),LocalDate.of(2026,1,1),LocalDate.of(2026,2,1))).isInstanceOf(IllegalArgumentException.class);var x=new SuccessionCycle("A","C1","Cycle",null,"p",1,"fp","ch",LocalDate.of(2026,1,1),LocalDate.of(2026,1,31),LocalDate.of(2026,2,28));x.open("admin","Approved opening",Instant.now());assertThat(x.getStatus()).isEqualTo(SuccessionCycle.Status.OPEN);assertThatThrownBy(()->x.update("Other",null,"p",1,"fp","ch",LocalDate.now(),LocalDate.now(),LocalDate.now())).isInstanceOf(IllegalLifecycleTransitionException.class);}
 @Test void candidateRequiresNoticeOwnConsentAndIndependentEligibilityReviewer(){var d=designation();var employee=new HumanResourceAssessmentSubject(1L,"EMP-1","Employee One",true,10L,LocalDateTime.now(),20L,30L,"employee-fp",LocalDateTime.now(),Instant.now());var x=new SuccessionCandidate("A","cycle",d,SuccessionCandidate.IntakeType.AUTHORIZED_NOMINATION,"HR-1",employee,"Documented succession intake");assertThatThrownBy(()->x.consent("EMP-1","I consent",Instant.now())).isInstanceOf(IllegalLifecycleTransitionException.class);x.sendNotice("HR-1","Privacy notice and voluntary participation terms",Instant.now());assertThatThrownBy(()->x.consent("OTHER","I consent",Instant.now())).isInstanceOf(IllegalArgumentException.class);x.consent("EMP-1","I understand and consent voluntarily",Instant.now());x.submit("HR-1",Instant.now());assertThatThrownBy(()->x.decideEligibility(true,"EMP-1","Meets criteria",Instant.now())).isInstanceOf(IllegalArgumentException.class);x.decideEligibility(true,"COMMITTEE-1","All configured eligibility criteria were met",Instant.now());assertThat(x.getStatus()).isEqualTo(SuccessionCandidate.Status.ELIGIBLE);assertThat(x.getEligibilityOutcome()).isEqualTo("ELIGIBLE");}
 @Test void candidateMayWithdrawWithoutCreatingReadinessOrAppointmentAction(){var employee=new HumanResourceAssessmentSubject(1L,"EMP-1","Employee One",true,10L,LocalDateTime.now(),20L,30L,"employee-fp",LocalDateTime.now(),Instant.now());var x=new SuccessionCandidate("A","cycle",designation(),SuccessionCandidate.IntakeType.SELF_EXPRESSION_OF_INTEREST,"EMP-1",employee,"Expression of interest");x.withdraw("EMP-1","I no longer wish to participate",Instant.now());assertThat(x.getStatus()).isEqualTo(SuccessionCandidate.Status.WITHDRAWN);}
 private SuccessionCriticalPositionDesignation designation(){var target=new AdministrativePositionTarget(PositionTargetType.JOB_POSITION,20L,20L,"Division Chief",24L,1L,null,null,"target-fp",Instant.now());var d=new SuccessionCriticalPositionDesignation("A",target,"framework",1,"framework-fp","charter","Critical Division Chief","Continuity requirement",LocalDate.of(2025,1,1),LocalDate.of(2027,1,1));ReflectionTestUtils.setField(d,"id","designation");d.submit("maker",Instant.now());d.approve("approver","Committee approval",LocalDate.of(2025,1,1),null,Instant.now());return d;}
}
